#!/usr/bin/env Rscript
a<-commandArgs(FALSE);f<-grep("^--file=",a,value=TRUE);sd<-dirname(normalizePath(sub("^--file=","",f[1])));repo<-normalizePath(file.path(sd,"..",".."),mustWork=TRUE);d<-read.csv(file.path(repo,"data_public","figure_source_data","Figure9","Figure9B_locked_formal_numerical_input.csv"),check.names=FALSE);o<-do.call(rbind,lapply(unique(d$endpoint),function(e){z<-d[d$endpoint==e,];tt<-t.test(z$value[z$group=="Model"],z$value[z$group=="Control"],var.equal=TRUE);data.frame(endpoint=e,t=unname(tt$statistic),df=unname(tt$parameter),P=tt$p.value)}));o$BH_FDR<-p.adjust(o$P,"BH");ref<-read.csv(file.path(repo,"data_public","figure_source_data","Animal_numerical_data","animal_endpoint_multiplicity_BH.csv"),check.names=FALSE);ref<-ref[ref$Figure=="Figure 9"&ref$Panel=="B",c("Endpoint","Raw_P","BH_adjusted_P")];m<-merge(o,ref,by.x="endpoint",by.y="Endpoint");m$exact_PASS<-abs(m$P-m$Raw_P)<1e-12&abs(m$BH_FDR-m$BH_adjusted_P)<1e-12;dir.create(file.path(repo,"results_reproduced","imaging"),recursive=TRUE,showWarnings=FALSE);write.csv(m,file.path(repo,"results_reproduced","imaging","Figure9B_locked_statistics_reproduced.csv"),row.names=FALSE);stopifnot(nrow(m)==6,all(m$exact_PASS))
